function sanitize(str, maxLen = 8000) {
  if (!str) return { text: '', was_truncated: false, original_length: 0 };
  const raw = String(str);
  const original_length = raw.length;
  // Strip control chars, zero-width chars, bidi overrides (preserve \t, \n, \r)
  const clean = raw.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F\u200B-\u200D\uFEFF\u202A-\u202E\u2066-\u2069]/g, '');
  let finalText = clean;
  let was_truncated = false;
  if (clean.length > maxLen) {
    was_truncated = true;
    let cut = clean.lastIndexOf(' ', maxLen);
    if (cut < maxLen * 0.8) cut = maxLen;
    finalText = clean.substring(0, cut) + '\n[...TRUNCATED: Message exceeded 8,000 characters...]';
  }
  return { text: finalText, was_truncated, original_length };
}

const item = $input.first()?.json || {};
const subSan = sanitize(item.email_subject, 500);
const bodySan = sanitize(item.email_body, 8000);
const customerContext = item.customer_context || {};

const prompt = `You are an enterprise AI Insurance Customer Support & Claims Triage reasoning engine.

INPUT EMAIL:
Subject: ${subSan.text}
Body: ${bodySan.text}

RETRIEVED CUSTOMER DATABASE CONTEXT:
${JSON.stringify(customerContext, null, 2)}

TAXONOMY OF 24 INSURANCE INTENTS & PRIORITIES:
1. CLAIM_STATUS (High)
2. NEW_CLAIM (Critical)
3. CLAIM_DOCUMENTS (High)
4. CLAIM_DELAY (Critical)
5. CLAIM_APPROVAL (High)
6. CLAIM_REJECTION (Critical)
7. POLICY_DOCUMENT (Medium)
8. POLICY_DETAILS (Medium)
9. POLICY_EXPIRY (High)
10. RENEWAL (High)
11. RENEWAL_QUOTE (High)
12. PREMIUM_QUERY (Medium)
13. POLICY_CHANGE (Medium)
14. VEHICLE_CHANGE (High)
15. CANCELLATION (High)
16. REFUND (High)
17. PAYMENT (High)
18. NO_CLAIM_BONUS (Medium)
19. NETWORK_GARAGE (Medium)
20. CASHLESS_CLAIM (High)
21. ROADSIDE_ASSISTANCE (Critical)
22. INSPECTION (High)
23. GENERAL_QUERY (Low)
24. COMPLAINT (Critical)
25. FRAUD_SUSPICION (Critical)

STRICT GROUNDING RULES:
- NEVER invent claim numbers, policy numbers, dates, or rupee amounts not present in the customer context.
- If customer is unidentified, state that policy records could not be located.
- Return ONLY a valid JSON object without markdown or markdown code blocks.

REQUIRED JSON SCHEMA:
{
  "category": "Claims | Policy | Billing | Roadside | Support",
  "intent": "<One of the 24 intents>",
  "priority": "Low | Medium | High | Critical",
  "urgency_score": 1,
  "sentiment": "Positive | Neutral | Frustrated | Angry",
  "escalation_needed": 0,
  "summary": "1-2 sentence summary",
  "suggested_reply": "Professional plain-text reply to sender",
  "routed_to": "Claims Desk | Underwriting | Billing | Roadside Assist | Grievance Team"
}`;

return [{
  json: {
    inception_payload: {
      model: "mercury-2.5",
      messages: [{ role: "user", content: prompt }],
      response_format: { type: "json_object" },
      temperature: 0.1
    },
    customer_context: customerContext,
    email_subject: subSan.text,
    email_body: bodySan.text,
    was_truncated: bodySan.was_truncated,
    original_length: bodySan.original_length
  }
}];

const inputItem = $input.first();
const llmData = inputItem.json;
const promptData = $('Build Prompt & Payload')?.first()?.json || {};
const customerContext = promptData.customer_context || {};
const wasTruncated = promptData.was_truncated === true;
const originalLength = promptData.original_length || 0;

let parsed = null;
try {
  const rawText = llmData.choices?.[0]?.message?.content;
  if (rawText) {
    const cleaned = rawText.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
    parsed = JSON.parse(cleaned);
  }
} catch (err) {
  parsed = null;
}

if (!parsed || !parsed.intent) {
  let failSummary = "LLM classification failed or timed out. Defaulted to human review.";
  if (wasTruncated) {
    failSummary += ` [TRUNCATED from ${originalLength} chars]`;
  }
  return [{
    json: {
      category: "Support",
      intent: "GENERAL_QUERY",
      priority: "High",
      urgency_score: 4,
      sentiment: "Neutral",
      escalation_needed: 1,
      summary: failSummary,
      suggested_reply: "",
      routed_to: "Grievance Team",
      is_llm_failure: true,
      was_truncated: wasTruncated,
      original_length: originalLength,
      customer_context: customerContext,
      guardrail_payload: {
        suggested_reply: "",
        customer_context: customerContext
      }
    }
  }];
}

let finalSummary = String(parsed.summary || '');
if (wasTruncated) {
  finalSummary = `${finalSummary} [TRUNCATED from ${originalLength} chars]`.trim();
}

const cleanReply = String(parsed.suggested_reply || '');
return [{
  json: {
    category: String(parsed.category || 'Support'),
    intent: String(parsed.intent || 'GENERAL_QUERY'),
    priority: String(parsed.priority || 'Medium'),
    urgency_score: Math.min(5, Math.max(1, parseInt(parsed.urgency_score) || 1)),
    sentiment: String(parsed.sentiment || 'Neutral'),
    escalation_needed: parsed.escalation_needed ? 1 : 0,
    summary: finalSummary,
    suggested_reply: cleanReply,
    routed_to: String(parsed.routed_to || 'Claims Desk'),
    is_llm_failure: false,
    was_truncated: wasTruncated,
    original_length: originalLength,
    customer_context: customerContext,
    guardrail_payload: {
      suggested_reply: cleanReply,
      customer_context: customerContext
    }
  }
}];

const llm = $('Parse & Validate LLM JSON')?.first()?.json || {};
const guardrail = $input.first()?.json || {};

if (llm.is_llm_failure) {
  return [{
    json: {
      ...llm,
      guardrail_status: "REJECTED",
      rejection_reason: "LLM inference failed.",
      escalation_needed: 1,
      passed: false,
      suggested_reply: ""
    }
  }];
}

const guardrailPassed = guardrail.passed === true;
const finalEscalationNeeded = (!guardrailPassed) ? 1 : (llm.escalation_needed ? 1 : 0);
const finalSuggestedReply = guardrailPassed ? llm.suggested_reply : "";
const finalGuardrailStatus = guardrailPassed ? "PASSED" : "REJECTED";
const rejectionReason = guardrailPassed ? null : (guardrail.rejection_reason || "Ungrounded entities detected");

return [{
  json: {
    ...llm,
    suggested_reply: finalSuggestedReply,
    guardrail_status: finalGuardrailStatus,
    rejection_reason: rejectionReason,
    escalation_needed: finalEscalationNeeded,
    passed: guardrailPassed,
    entities_detected: guardrail.entities_detected || {}
  }
}];
